	"time"
	"unicode/utf8"

	"github.com/santhosh-tekuri/jsonschema/v6"
	"github.com/yetone/magpie/internal/appdir"
	"github.com/yetone/magpie/internal/claudecode"
	"github.com/yetone/magpie/internal/claudetui"
